// Phase 6 is already complete — skip the wrapper path entirely.
emit({ type: "phase_start", phase: 6, description: "post-execution workflow protocol" });

if (existsSync(resultPath)) {
  try {
    const raw = JSON.parse(readFileSync(resultPath, "utf-8")) as ExecutorResult & { pr_url?: string };
    // Short-circuit when Hermes wrote a terminal result that includes a PR URL.
    // Covers both "in_review" (success) and "blocked" with pr_url (e.g. tests_failed
    // after the agent already pushed and opened a PR) — in both cases the wrapper
    // fallback must not overwrite the real status with "blocked:no_changes".
    const hermesDone =
      (raw.terminal_status === "in_review" || raw.terminal_status === "blocked") &&
      typeof raw.pr_url === "string" &&
      raw.pr_url !== "";
    if (hermesDone) {
      emit({ type: "phase_done", phase: 6, pr_url: raw.pr_url, source: "hermes_wrote_result" });
      if (logSinkEnabled) {
        flushLog(mgmtDir, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, raw.terminal_status, sshKeyPath, emit);
        logFlushed = true;
      }
      return;
    }
